"""Base class for code generators."""

from collections.abc import Callable
from typing import Any, ClassVar


def handles(*types: type) -> Callable[[Callable[..., str]], Callable[..., str]]:
    """Mark a Generator method as the code handler for the given node types.

    Note:
        This is used instead of functools.singledispatchmethod, which adds several Python
        frames to every call (and, before Python 3.13, builds a new bound function on every
        attribute access). Code generation recurses once per node, so those frames exhaust the
        recursion limit on deep expressions. Generators call the handler directly from their
        operand method (eg CGenerator.emit), which keeps the recursion at two frames per node.
    """

    def mark(method: Callable[..., str]) -> Callable[..., str]:
        method._handles = types  # type: ignore[attr-defined]
        return method

    return mark


def _collect_handlers(cls: type) -> dict[type, Callable[..., str]]:
    """Get the handlers that a class defines itself, keyed by node type."""
    return {t: f for f in vars(cls).values() for t in getattr(f, "_handles", ())}


class Generator:
    """Base class for generators of code for lowered UFLx expressions and code-structure nodes.

    The code for each node type is generated by a method marked with @handles(type); a node is
    handled by the handler of the first class in its MRO that has one. Each target is a
    subclass with its own handlers, and all generation state lives on the generator instance,
    so generators for different targets (or with different options) are independent.
    """

    #: Name of the target language, used in error messages.
    target: ClassVar[str] = "code"
    # Node type -> handler, filled from the @handles methods when the class is created.
    _handlers: ClassVar[dict[type, Callable[..., str]]] = {}
    # Node type -> resolved handler (including inherited ones), filled on first use.
    _resolved: ClassVar[dict[type, Callable[..., str]]] = {}

    def __init_subclass__(cls, **kwargs):
        """Collect the handlers of a subclass, on top of those it inherits."""
        super().__init_subclass__(**kwargs)
        cls._handlers = {**cls._handlers, **_collect_handlers(cls)}
        cls._resolved = {}

    @classmethod
    def _handler(cls, node_type: type) -> Callable[..., str]:
        """Get the handler for a node type."""
        try:
            return cls._resolved[node_type]
        except KeyError:
            for base in node_type.__mro__:
                if base in cls._handlers:
                    cls._resolved[node_type] = cls._handlers[base]
                    return cls._handlers[base]
            raise NotImplementedError(
                f"{cls.target} generation is not implemented for {node_type.__name__}"
            ) from None

    def code(self, node: Any) -> str:
        """Generate code for a node."""
        return self._handler(type(node))(self, node)
